/**
 * Selects where framework session state is durably mirrored.
 *
 * Architecture v1 honors authored storage. Without it, Cursor-managed
 * hosting selects managed storage, while self-hosted agents use
 * `--state-root`. Architecture v2 rejects authored storage and selects the
 * managed backend only on Cursor-managed hosting.
 *
 * When managed storage is selected, framework-owned session records, event
 * transcripts, and continuation state stay separate from author-facing files
 * and KV.
 */
import { cursorHostedFiles } from "../files-backends/cursor-hosted.js";
import { defineStorage } from "../storage.js";
import { AGENT_SERVE_DEPLOYMENT_ID_ENV_VAR, cursorHostedStorage, } from "../storage-backends/cursor-hosted.js";
import { cursorHostedStorageV2 } from "../storage-backends/cursor-hosted-v2.js";
import { resolveApiKeySync } from "./cursor/credentials.js";
import { composeFrameworkStorage, fileSinkStorageCore, frameworkGuardedCas, } from "./framework-file-storage.js";
import { isCursorManagedV2Hosting, resolveAgentV2Hosting } from "./v2-hosting.js";
/**
 * Pick the backend for framework session state.
 *
 * Returns `undefined` when there is no mirror, in which case the local state
 * directory is the only copy.
 */
export function selectFrameworkStorageDefinition(input) {
    if (input.architecture !== "v2") {
        if (input.authored !== undefined) {
            return input.authored;
        }
        const env = input.env ?? process.env;
        if ((env[AGENT_SERVE_DEPLOYMENT_ID_ENV_VAR] ?? "").trim() !== "") {
            // Managed v1 deployment with no authored sink: keep the Cursor-hosted
            // mirror (lazy restore) so agents can delete `agent/storage.ts`
            // without losing durability while they still run architecture v1.
            return defineStorage({
                name: "cursor-hosted (lazy restore)",
                policy: { restore: "off" },
                ...cursorHostedStorage(),
            });
        }
        return undefined;
    }
    if (input.authored !== undefined) {
        // Discovery rejects agent/storage.ts on v2 before an engine is built;
        // an authored definition reaching this point is a wiring bug. Raise
        // rather than silently discard what the author believes is configured.
        throw new Error('defineStorage (agent/storage.ts) is not supported on architecture "v2": storage is platform-selected. Delete the file.');
    }
    const hosting = resolveAgentV2Hosting({
        architecture: input.architecture,
        env: input.env,
    });
    if (!isCursorManagedV2Hosting(hosting)) {
        // Self-hosted v2: the state root is the durable copy.
        return undefined;
    }
    // Managed v2 hosts restore sessions lazily by continuation or session id.
    // Turn completion still waits for the session record to reach storage.
    // A persistent slot never restores: its own `/state` is the live copy and
    // the mirror exists so the dashboard survives the VM, not the other way.
    const policy = {
        restore: "off",
    };
    const resolveApiKey = () => resolveApiKeySync()?.apiKey;
    // Author KV, CAS coordination, and evals stay separate from framework-owned
    // session state. Session listing reads the framework side of that split.
    const kv = cursorHostedStorageV2({ resolveApiKey });
    return defineStorage({
        name: "cursor-hosted (framework files)",
        policy,
        ...kv,
        ...composeFrameworkStorage({
            kv,
            files: fileSinkStorageCore(cursorHostedFiles({
                resolveStoreSourceId: () => hosting.resolveStoreIds().frameworkStoreSourceId,
                resolveApiKey,
            })),
        }),
        // CAS stays on the KV proxy but must refuse framework-file keys, or a
        // future coordination path would split-brain against the plain core.
        cas: frameworkGuardedCas(kv.cas),
    });
}
